index 0000000..6e5a942
--- /dev/null
+++ b/src/bugmiester/packs/cpp/__init__.py
@@ -0,0 +1,17 @@
+"""C++ language pack package (MVP curriculum). Config id: cpp."""
+
+from __future__ import annotations
+
+__all__ = ["CPP_PACK", "SEED_POOL"]
+
+
+def __getattr__(name: str):
+    if name == "SEED_POOL":
+        from bugmiester.packs.cpp.seeds import SEED_POOL
+
+        return SEED_POOL
+    if name == "CPP_PACK":
+        from bugmiester.packs.cpp.pack import CPP_PACK
+
+        return CPP_PACK
+    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
