+"""C++ MVP canned fallbacks when generate attempts are exhausted."""
+
+from __future__ import annotations
+
+from bugmiester.freshness import GeneratedSnippet
+from bugmiester.llm.mock_provider import MockSnippet
+from bugmiester.scenario import ScenarioSeed
