+_FALLBACK_BANK: dict[str, MockSnippet] = {
+    "arr-off-by-one": MockSnippet(
+        code="""\
+int main() {
+  int a[3] = {1, 2, 3};
+  int total = 0;
+  for (int i = 0; i <= 3; ++i) total += a[i];
+  return total;
+}
+""",
+        bug_summary="Loop uses <= so the last index is out of bounds",
+        bug_category="arrays",
+        difficulty="beginner",
+        hints=("Use i < n",),
+        keywords=("off-by-one", "array", "bounds", "loop"),
+    ),
+    "arr-decay-sizeof": MockSnippet(
+        code="""\
+int len(int a[]) { return sizeof(a) / sizeof(*a); }
+int main() {
+  int a[8] = {};
+  return len(a);
+}
+""",
+        bug_summary="sizeof on a decayed pointer is not the array length",
+        bug_category="arrays",
+        difficulty="beginner",
+        hints=("Pass the length explicitly",),
+        keywords=("sizeof", "decay", "pointer", "array"),
+    ),
+    "str-c-str-temp": MockSnippet(
+        code="""\
+#include <string>
+const char* p = std::string("x").c_str();
+int main() { return p[0]; }
+""",
+        bug_summary="c_str() from a temporary string dangles after the full expression",
+        bug_category="strings",
+        difficulty="beginner",
+        hints=("Keep the std::string alive",),
+        keywords=("c_str", "temporary", "dangling", "string"),
+    ),
+    "str-view-temp": MockSnippet(
+        code="""\
+#include <string>
+#include <string_view>
+std::string_view v = std::string("x");
+int main() { return v.empty(); }
+""",
+        bug_summary="string_view bound to a temporary string becomes dangling",
+        bug_category="strings",
+        difficulty="beginner",
+        hints=("Keep the owning string alive",),
+        keywords=("string_view", "temporary", "dangling", "lifetime"),
+    ),
+    "int-signed-overflow": MockSnippet(
+        code="""\
+#include <climits>
+int main() { return INT_MAX + 1; }
+""",
+        bug_summary="Signed integer overflow is undefined behavior",
+        bug_category="integers",
+        difficulty="beginner",
+        hints=("Check before adding near INT_MAX",),
+        keywords=("overflow", "signed", "UB", "INT_MAX"),
+    ),
+    "int-unsigned-wrap": MockSnippet(
+        code="""\
+int main() { return (int)(0u - 1u); }
+""",
+        bug_summary="Unsigned subtraction wraps instead of reporting underflow",
+        bug_category="integers",
+        difficulty="beginner",
+        hints=("Check before subtracting unsigned values",),
+        keywords=("unsigned", "wrap", "underflow", "subtraction"),
+    ),
+    "ptr-null-deref": MockSnippet(
+        code="""\
+int main() {
+  int* p = nullptr;
+  return *p;
+}
+""",
+        bug_summary="Null pointer is dereferenced",
+        bug_category="pointers",
+        difficulty="beginner",
+        hints=("Check for nullptr before deref",),
+        keywords=("nullptr", "dereference", "null", "pointer"),
+    ),
+    "ptr-dangling-stack": MockSnippet(
+        code="""\
+int* f() {
+  int x = 1;
+  return &x;
+}
+int main() { return *f(); }
+""",
+        bug_summary="Function returns a pointer to a stack local",
+        bug_category="pointers",
+        difficulty="beginner",
+        hints=("Cannot return addresses of locals",),
+        keywords=("dangling", "stack", "local", "pointer"),
+    ),
+    "vec-index-oob": MockSnippet(
+        code="""\
+#include <vector>
+int main() {
+  std::vector<int> v{1};
+  return v[v.size()];
+}
+""",
+        bug_summary="Indexing with size() is one past the last valid index",
+        bug_category="vectors",
+        difficulty="beginner",
+        hints=("Last index is size() - 1",),
+        keywords=("vector", "operator[]", "size", "out-of-bounds"),
+    ),
+    "vec-invalidate-push": MockSnippet(
+        code="""\
+#include <vector>
+int main() {
+  std::vector<int> v{1};
+  int* p = &v[0];
+  v.push_back(2);
+  return *p;
+}
+""",
+        bug_summary="Pointer into a vector is invalidated by push_back reallocation",
+        bug_category="vectors",
+        difficulty="beginner",
+        hints=("Do not keep pointers across growth",),
+        keywords=("push_back", "invalidate", "pointer", "vector"),
+    ),
+    "iter-erase-continue": MockSnippet(
+        code="""\
