+        bug_summary="Assignment used in the if condition instead of equality",
+        bug_category="booleans",
+        difficulty="beginner",
+        hints=("Use == to compare",),
+        keywords=("=", "==", "assignment", "condition"),
+    ),
+    "cmp-float-eq": MockSnippet(
+        code="""\
