+""",
+        bug_summary="Floating point == fails for values that look equal in decimal",
+        bug_category="equality",
+        difficulty="beginner",
+        hints=("Compare with an epsilon",),
+        keywords=("float", "==", "equality", "precision"),
+    ),
+    "life-ref-local": MockSnippet(
+        code="""\
