+""",
+        bug_summary="string_view outlives the string buffer it points into",
+        bug_category="lifetime",
+        difficulty="advanced",
+        hints=("Owning string is destroyed before the view is used",),
+        keywords=("string_view", "lifetime", "dangling", "buffer"),
+    ),
+    "move-use-after": MockSnippet(
+        code="""\
+#include <string>
+#include <utility>
+int main() {
+  std::string a = "x";
+  std::string b = std::move(a);
+  return (int)a.size();
+}
+""",
+        bug_summary="Moved-from string is used as if it still held the original data",
+        bug_category="move",
+        difficulty="intermediate",
+        hints=("Treat moved-from objects as unspecified",),
+        keywords=("move", "use-after-move", "string", "unspecified"),
+    ),
+    "move-self-assign": MockSnippet(
+        code="""\
+struct Buf {
+  int* p;
+  Buf() : p(new int(1)) {}
+  Buf& operator=(Buf&& o) noexcept {
+    delete p;
+    p = o.p;
