@@ -0,0 +1,118 @@
+"""C++ language pack MVP smoke tests (config id: cpp)."""
+
+from __future__ import annotations
+
+from pathlib import Path
+
+import yaml
+
+from bugmiester.config import ensure_app_dir, load_settings
+from bugmiester.freshness import pick_seed
+from bugmiester.llm.facade import generate_bug
+from bugmiester.packs import get_pack
+
+
+def _write_cpp_mock_config(examples: Path) -> None:
+    examples.mkdir(parents=True, exist_ok=True)
+    (examples / ".env.example").write_text(
+        "OPENAI_API_KEY=replace-me\n",
+        encoding="utf-8",
+    )
+    config = {
+        "llm": {"provider": "mock", "model": "mock"},
+        "game": {
+            "bugs_per_round": 10,
+            "languagepack": "cpp",
+            "mix": "senior_mix",
+        },
+        "scoring": {"mode": "keyword", "points_per_bug": 10, "partial_credit": True},
+        "freshness": {
+            "avoid_list_max": 20,
+            "similarity_reject_threshold": 0.99,
+            "max_generate_attempts": 2,
+        },
+        "resilience": {
+            "max_judge_calls_per_submit": 0,
+            "use_canned_fallback_on_generate_exhaustion": True,
+            "prefetch_next_bug": False,
+        },
+        "recovery": {"enabled": False},
+        "adaptation": {"enabled": False},
+        "metrics": {"log_per_bug": False, "log_dir_name": "logs"},
+        "reports": {"enabled": False, "dir_name": "reports"},
+        "feedback": {"analyze_on_ops_load": False},
+        "server": {"host": "127.0.0.1", "port": 8765},
+    }
+    (examples / "config.yaml.example").write_text(
+        yaml.safe_dump(config, sort_keys=False),
+        encoding="utf-8",
+    )
+
+
+def test_cpp_senior_mix_picks_across_bands() -> None:
+    pack = get_pack("cpp")
+    used: set[str] = set()
+    phases: list[str] = []
+    for _ in range(10):
+        seed = pick_seed(
+            pack.seed_pool,
+            used,
+            mix="senior_mix",
+            bugs_per_round=10,
+            pack=pack,
+        )
+        used.add(seed.seed_id)
+        from bugmiester.mix import adaptive_phase
+
+        phases.append(
+            adaptive_phase(len(used) - 1, 10, mix="senior_mix")
+        )
+    assert phases[0] == "slop"
+    assert phases[-1] == "gnarly"
+    assert any(p == "senior" for p in phases)
+
+
+def test_cpp_mock_generate_round(tmp_path: Path) -> None:
+    examples = tmp_path / "examples"
+    app_dir = tmp_path / "app"
+    _write_cpp_mock_config(examples)
+    ensure_app_dir(app_dir=app_dir, examples_dir=examples)
+    settings = load_settings(
+        app_dir=app_dir,
+        examples_dir=examples,
+        load_env_into_process=False,
+    )
+    assert settings.game.languagepack == "cpp"
+    assert settings.pack.id == "cpp"
+    assert settings.pack.display_name == "C++"
+
+    used: set[str] = set()
+    history: list = []
+    for _ in range(10):
+        result = generate_bug(
+            settings,
+            used_seed_ids=used,
+            history=history,
+        )
+        used.add(result.seed.seed_id)
+        code = result.snippet.code
+        assert (
+            "int " in code
+            or "void " in code
+            or "std::" in code
+            or "struct " in code
+            or "class " in code
+            or "#include" in code
+            or "auto " in code
+            or "template" in code
+        )
+        assert result.snippet.bug_summary
+
+
+def test_cpp_fallback_covers_every_seed() -> None:
+    pack = get_pack("cpp")
+    for seed in pack.seed_pool:
+        snippet = pack.fallback_for_seed(seed)
+        assert snippet.code.strip()
+        assert snippet.bug_summary
+        assert snippet.seed is seed
