+"""Rust MVP scenario seed pool (~40 seeds)."""
+
+from __future__ import annotations
+
+from bugmiester.scenario import ScenarioSeed
+
+SEED_POOL: tuple[ScenarioSeed, ...] = (
+    ScenarioSeed(
+        "opt-unwrap-none",
+        "Option",
+        "unwrap on a None path",
+        "must call unwrap on an Option that can be None",
+    ),
+    ScenarioSeed(
+        "opt-or-default",
+        "Option",
+        "or() evaluated eagerly for both arms",
+        "must use or with a computed default so both sides run",
+    ),
+    ScenarioSeed(
+        "res-unwrap-err",
+        "Result",
+        "unwrap on an Err path",
+        "must call unwrap on a Result that can be Err",
+    ),
+    ScenarioSeed(
+        "res-map-err-drop",
+        "Result",
+        "map_err result discarded so errors are ignored",
+        "must call map_err and ignore the returned Result",
+    ),
+    ScenarioSeed(
+        "int-as-trunc",
+        "integers",
+        "as cast truncates a large u32 to u8",
+        "must cast with as so high bits are discarded",
+    ),
+    ScenarioSeed(
+        "int-wrapping-add",
+        "integers",
+        "wrapping_add used when overflow should be an error",
+        "must use wrapping_add so overflow wraps silently",
+    ),
+    ScenarioSeed(
+        "float-eq",
+        "equality",
+        "floating point compared with ==",
+        "must compare floats with ==",
+    ),
+    ScenarioSeed(
+        "str-index-byte",
+        "strings",
+        "String indexed by byte as if by char",
+        "must index a multi-byte UTF-8 string by byte offset",
+    ),
+    ScenarioSeed(
+        "str-chars-nth",
+        "strings",
+        "chars().nth used in a hot loop as random access",
+        "must repeatedly call chars().nth for many indices",
+    ),
+    ScenarioSeed(
+        "slice-off-by-one",
+        "slices",
+        "slice end index one past the last wanted element",
+        "must use an exclusive range that skips the last intended item",
+    ),
+    ScenarioSeed(
+        "vec-index-oob",
+        "vectors",
+        "indexing past the last element",
+        "must index with an out-of-bounds usize",
+    ),
+    ScenarioSeed(
+        "vec-retain-index",
+        "vectors",
+        "indices assumed stable while removing elements",
+        "must remove by index while looping ascending indices",
+    ),
+    ScenarioSeed(
+        "iter-consumed",
+        "iterators",
+        "iterator used after it was already consumed",
+        "must call a consuming adapter then use the same iterator again",
+    ),
+    ScenarioSeed(
+        "iter-skip-take",
+        "iterators",
+        "skip and take order reversed",
+        "must call take before skip so the wrong window is kept",
+    ),
+    ScenarioSeed(
+        "match-wildcard-first",
+        "match",
+        "wildcard arm placed before specific arms",
+        "must put a catch-all arm before a more specific pattern",
+    ),
+    ScenarioSeed(
+        "match-guard-overlap",
+        "match",
+        "match guard order makes a later arm unreachable in practice",
+        "must order guards so an earlier arm always wins incorrectly",
+    ),
+    ScenarioSeed(
+        "bool-and-assign",
+        "booleans",
+        "& used where && short-circuit was intended",
+        "must use & on bools so both sides always evaluate",
+    ),
+    ScenarioSeed(
+        "copy-mutate-orig",
+        "Copy",
+        "Copy type mutated through a copy assuming shared state",
+        "must mutate a Copy value and expect the original to change",
+    ),
+    ScenarioSeed(
+        "clone-shallow-rc",
+        "Clone",
+        "Rc clone treated as a deep copy of interior data",
+        "must clone an Rc and mutate through one handle expecting isolation",
+    ),
+    ScenarioSeed(
+        "drop-order",
+        "Drop",
+        "temp Drop guard released before the critical section ends",
+        "must let a lock guard drop before the shared write finishes",
+    ),
+    ScenarioSeed(
+        "refcell-borrow-mut",
+        "interior mutability",
+        "borrow_mut while an immutable borrow is still live",
+        "must call borrow_mut while a borrow still exists",
+    ),
+    ScenarioSeed(
+        "cell-get-set-race",
+        "interior mutability",
+        "Cell get-modify-set loses updates",
+        "must read Cell, compute, and set without atomicity across calls",
+    ),
+    ScenarioSeed(
+        "arc-mutex-poison",
+        "concurrency",
+        "lock unwrap ignores poison after a panic",
+        "must unwrap a poisoned Mutex lock",
+    ),
+    ScenarioSeed(
+        "arc-no-join",
+        "concurrency",
+        "spawned thread not joined before reading shared result",
+        "must spawn a thread that writes shared state and read it without join",
+    ),
+    ScenarioSeed(
+        "race-atomic-load-store",
+        "racey threads",
+        "separate load and store on AtomicUsize instead of fetch_add",
+        "must load, add, store on an Atomic without fetch_add",
+    ),
+    ScenarioSeed(
+        "race-check-hashmap",
+        "racey threads",
+        "check-then-insert on a shared HashMap without holding the lock",
+        "must unlock between contains_key and insert",
+    ),
+    ScenarioSeed(
+        "async-block-on",
+        "async",
+        "async fn called without await or block_on",
+        "must call an async function like a normal function and use the result",
+    ),
+    ScenarioSeed(
+        "async-join-partial",
+        "async",
+        "join! abandons siblings when one fails",
+        "must use join! where one future errors and others are needed",
+    ),
+    ScenarioSeed(
+        "hash-random-order",
+        "HashMap",
+        "HashMap iteration order assumed stable",
+        "must assert a specific iteration order from a HashMap",
+    ),
+    ScenarioSeed(
+        "hash-entry-or-default",
+        "HashMap",
+        "or_default used then overwritten incorrectly",
+        "must call or_default and then assign a value that drops prior inserts",
+    ),
+    ScenarioSeed(
+        "default-derive-zero",
+        "Default",
+        "Default derive used when zero is an invalid state",
+        "must rely on Default for a type where zero fields are wrong",
+    ),
+    ScenarioSeed(
+        "from-parse-trim",
+        "parsing",
+        "parse without trimming whitespace",
+        "must parse a string that still has leading or trailing spaces",
+    ),
+    ScenarioSeed(
+        "fmt-debug-eq",
+        "formatting",
+        "Debug output compared as if it were Display",
+        "must format with {:?} and compare to a Display-style string",
+    ),
+    ScenarioSeed(
+        "lifetime-return-local",
+        "lifetimes",
+        "function returns a reference to a local",
+        "must return a reference to a local variable",
+    ),
+    ScenarioSeed(
+        "borrow-split-mut",
+        "borrowing",
+        "two mutable borrows of overlapping slice regions",
+        "must mutably borrow overlapping parts of the same slice",
+    ),
+    ScenarioSeed(
+        "move-use-after",
+        "ownership",
+        "value used after move into a function",
+        "must use a non-Copy value after moving it",
+    ),
+    ScenarioSeed(
+        "unsafe-null-deref",
+        "unsafe",
+        "raw pointer dereferenced without null check",
+        "must dereference a null raw pointer",
+    ),
+    ScenarioSeed(
+        "unsafe-alias-mut",
+        "unsafe",
+        "aliased mutable raw pointers written concurrently in logic",
+        "must create two &mut via raw pointers to the same place",
+    ),
+    ScenarioSeed(
+        "endian-cast",
+        "bytes",
+        "integer bytes interpreted with the wrong endianness",
+        "must use to_ne_bytes or from_ne_bytes when a fixed endian was required",
+    ),
+    ScenarioSeed(
+        "loop-break-value",
+        "control flow",
+        "loop break value discarded by a later return",
+        "must break with a value then ignore it and return something else",
+    ),
+)
